#!/usr/bin/env python3
"""Test the actual scratch-sector safety gates with a simulated block device."""
from pathlib import Path
import subprocess
import tempfile

source = (Path(__file__).resolve().parent.parent / 'shim/gm9pro-write-probe.inc').read_text()
start = source.index('/* This only sends CMD13')
end = source.index('static int wp_userdata_name', start)
preamble = '#include <stdint.h>\n#include <assert.h>\n#include <string.h>\n#include <stdio.h>\nstatic uint32_t le32(const uint8_t *p) { return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24; }\nstatic uint32_t crc32(const uint8_t *p, unsigned n) { uint32_t c=~0U; while(n--) { c^=*p++; for(int i=0;i<8;i++) c=(c>>1)^(0xedb88320U & (0U-(c&1))); } return ~c; }\n'
stub = 'static int mock_writes, mock_fail_first, mock_fail_restore;\nstatic uint8_t disk_sector[512], disk_original[512], ext[512], header[512], table[2048], hfs[512];\nstatic uint32_t scratch_lba = 196952;\nstatic const char *last_message;\nstatic int read_block(unsigned cmd, uint32_t lba, uint8_t *out) {\n    const uint8_t *p = NULL;\n    if (cmd == 8) p = ext;\n    else if (cmd != 17) return -1;\n    else if (lba == 1) p = header;\n    else if (lba >= 2 && lba <= 5) p = table + (lba - 2) * 512;\n    else if (lba == 1002) p = hfs;\n    else if (lba == scratch_lba) p = disk_sector;\n    if (!p) return -1;\n    memcpy(out,p,512); return 0;\n}\nstatic int wp_write_one(uint32_t lba, const uint8_t *data, int *sent) {\n    assert(lba == scratch_lba); *sent = 1; mock_writes++;\n    if (mock_fail_restore && mock_writes == 2) return -1;\n    memcpy(disk_sector,data,512);\n    if (mock_fail_first && mock_writes == 1) return -1;\n    return 0;\n}\nstatic void puts_uart(const char *s) { last_message = s; }\nstatic void hex(const char *s, uint64_t v) { (void)s; (void)v; }\n'
tests = 'static void u32(uint8_t*p,uint32_t v){for(int i=0;i<4;i++)p[i]=v>>(i*8);}\nstatic void u64(uint8_t*p,uint64_t v){u32(p,v);u32(p+4,v>>32);}\nstatic void fix(void){u32(header+88,crc32(table,sizeof(table)));u32(header+16,0);u32(header+16,crc32(header,92));}\nstatic void fixture(void) {\n memset(ext,0,512);memset(header,0,512);memset(table,0,sizeof(table));memset(hfs,0,512);memset(wp_first,0,sizeof(wp_first));memset(wp_last,0,sizeof(wp_last));\n mock_writes=mock_fail_first=mock_fail_restore=0;last_message="";ext[192]=8;u32(ext+212,200000);\n memcpy(header,"EFI PART",8);u32(header+12,92);u64(header+24,1);u64(header+32,199999);u64(header+40,34);u64(header+48,199966);u64(header+72,2);u32(header+80,16);u32(header+84,128);\n table[0]=1;u64(table+32,1000);u64(table+40,199000);const char *n="userdata";for(int i=0;n[i];i++)table[56+i*2]=n[i];fix();\n hfs[0]=\'H\';hfs[1]=\'X\';hfs[42]=0x10;hfs[46]=3;hfs[47]=0xe8;\n for(int i=0;i<512;i++)disk_sector[i]=disk_original[i]=(uint8_t)i;\n}\nint main(void) {\n fixture();gm9_write_probe();assert(mock_writes==2&&!memcmp(disk_sector,disk_original,512)&&strstr(last_message,"WRITE PROBE PASS"));\n fixture();ext[33]=1;gm9_write_probe();assert(!mock_writes&&strstr(last_message,"REFUSED"));\n fixture();ext[15]=1;gm9_write_probe();assert(!mock_writes);\n fixture();ext[171]=1;gm9_write_probe();assert(!mock_writes);\n fixture();table[200]^=1;gm9_write_probe();assert(!mock_writes&&strstr(last_message,"GPT entries invalid"));\n fixture();table[128]=2;u64(table+160,1500);u64(table+168,1600);fix();gm9_write_probe();assert(!mock_writes&&strstr(last_message,"overlaps"));\n fixture();hfs[0]=\'X\';gm9_write_probe();assert(!mock_writes&&strstr(last_message,"not an HFS"));\n fixture();hfs[44]=0xff;hfs[45]=0xff;gm9_write_probe();assert(!mock_writes&&strstr(last_message,"No verified space"));\n fixture();mock_fail_first=1;gm9_write_probe();assert(mock_writes==2&&!memcmp(disk_sector,disk_original,512)&&strstr(last_message,"original sector restored"));\n fixture();mock_fail_restore=1;gm9_write_probe();assert(mock_writes==2&&memcmp(disk_sector,disk_original,512)&&strstr(last_message,"restore not verified"));\n puts("Write probe safety gates, scratch restore and failure paths PASS");return 0;\n}\n'
with tempfile.TemporaryDirectory() as directory:
    c = Path(directory) / 'test.c'
    executable = Path(directory) / 'test'
    c.write_text(preamble + source[:start] + stub + source[end:] + tests)
    subprocess.run(['cc', '-std=c11', '-Wall', '-Wextra', '-Werror', str(c), '-o', str(executable)], check=True)
    subprocess.run([str(executable)], check=True)
